        console.log("发送给后端的数据:", {
          image: base64Image
        });
        const response = await fetch('/api/vision', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json'
          },
          body: JSON.stringify({
            image: base64Image
          })
        });
        if (!response.ok) {
          throw new Error('图片分析失败');
